// Bundles the Hono app into one file for the Supabase Edge Function (supabase/functions/aangan/app.ts).
import { execFileSync } from 'node:child_process';
execFileSync('node', ['scripts/build-pages.js'], { stdio: 'inherit' });
execFileSync('npx', ['esbuild', 'src/edge.ts', '--bundle', '--format=esm', '--platform=node', '--target=es2022',
  '--outfile=supabase/functions/aangan/app.ts', '--banner:js=// Generated by scripts/build-edge.js. Do not edit.\n// @ts-nocheck',
  '--external:node:*', '--external:cloudflare:sockets'], { stdio: 'inherit' });
// Deno wants the node: prefix on built-in modules; esbuild leaves bare names from the postgres driver.
import { readFileSync, writeFileSync, copyFileSync } from 'node:fs';
const f = 'supabase/functions/aangan/app.ts';
copyFileSync('src/edge-entry.ts', 'supabase/functions/aangan/index.ts');
const builtins = ['os', 'fs', 'net', 'tls', 'crypto', 'stream', 'perf_hooks', 'events', 'buffer', 'util', 'string_decoder', 'path', 'url'];
let s = readFileSync(f, 'utf8');
for (const b of builtins) s = s.replaceAll(`from "${b}"`, `from "node:${b}"`);
writeFileSync(f, s);
